const IRDotProjector = ({ active, color = 'rgba(34, 197, 94' }) => {
  const canvasRef = useRef(null);

  useEffect(() => {
    if (!active || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let frame = 0;
    const dots = [];
    const rows = 45;
    const cols = 60;

    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        dots.push({ x: (c / cols) * 100, y: (r / rows) * 100, phase: Math.random() * Math.PI * 2 });
      }
    }

    const animate = () => {
      frame++;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const w = canvas.width;
      const h = canvas.height;

      dots.forEach(dot => {
        const dx = dot.x - 50;
        const dy = dot.y - 50;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const warp = 1 + Math.sin(frame * 0.04 + dist * 0.12) * 0.03;

        const finalX = (dx * warp + 50) * (w / 100);
        const finalY = (dy * warp + 50) * (h / 100);

        ctx.fillStyle = `${color}, ${0.4 + Math.sin(frame * 0.1 + dot.phase) * 0.2})`;
        ctx.beginPath();
        ctx.arc(finalX, finalY, 1.3, 0, Math.PI * 2);
        ctx.fill();
      });

      requestAnimationFrame(animate);
    };

    const handle = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(handle);
  }, [active, color]);

  return <canvas ref={canvasRef} className={`absolute inset-0 pointer-events-none transition-opacity duration-1000 ${active ? 'opacity-70' : 'opacity-0'}`} width={1000} height={1000} />;
};

export default function App() {
  const [theme, setTheme] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('theme') || 'light';
    }
    return 'light';
  });
  const [status, setStatus] = useState('idle');
  const [result, setResult] = useState(null);
  const [capturedImage, setCapturedImage] = useState(null);
  const [error, setError] = useState(null);
  const [isCalibrating, setIsCalibrating] = useState(false);
  const [calibratedIPD, setCalibratedIPD] = useState(null);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => setTheme(prev => prev === 'light' ? 'dark' : 'light');

  const captureFrame = useCallback(async (isFinal = true) => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);
        const dataUrl = canvasRef.current.toDataURL('image/jpeg', 0.9);
        if (isFinal) {
          setCapturedImage(dataUrl);
          if (videoRef.current.srcObject) {
            videoRef.current.srcObject.getTracks().forEach(t => t.stop());
          }
        }
        return dataUrl;
      }
    }
    return null;
  }, []);

  const runIPDAnalysis = async (imageSource = null) => {
    setStatus('analyzing');
    const frame = imageSource || (await captureFrame(true));
    if (frame) {
      try {
        const base64 = frame.split(',')[1];
        const res = await analyzeIPD(base64);

        setResult(res);
        setCapturedImage(frame);
        setStatus('completed');
      } catch (e) {
        setError("Clinical analysis failed. Please ensure your eyes are clearly visible and well-lit.");
        setStatus('error');
      }
    }
  };

  const handleFileUpload = (e) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const dataUrl = event.target?.result as string;
        runIPDAnalysis(dataUrl);
      };
      reader.readAsDataURL(file);
    }
  };

  const startCamera = async () => {
    try {
      setStatus('capturing');
      setError(null);
      setCalibratedIPD(null);
      setResult(null);
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'user', width: { ideal: 1920 }, height: { ideal: 1080 } } 
      });
      if (videoRef.current) videoRef.current.srcObject = stream;

      setIsCalibrating(true);
      // Faster pre-calibration window (500ms instead of 1500ms)
      setTimeout(async () => {
        const frame = await captureFrame(false);
        if (frame) {
          const est = await preCalibrateIPD(frame.split(',')[1]);
          setCalibratedIPD(est.ipdMm);
        }
        setIsCalibrating(false);
      }, 500);
    } catch (err) {
      setError("Camera unavailable. Check permissions.");
      setStatus('idle');
    }
  };

  const reset = () => {
    setStatus('idle');
    setResult(null);
    setCapturedImage(null);
    setError(null);
    if (videoRef.current && videoRef.current.srcObject) {
      videoRef.current.srcObject.getTracks().forEach(t => t.stop());
    }
  };

  const isDarkMode = theme === 'dark';

  return (
    <div className={`min-h-screen flex flex-col transition-all duration-500 ${isDarkMode ? 'bg-slate-950 text-slate-100' : 'bg-slate-50 text-slate-900'}`}>
      <Header authorized={status === 'completed'} theme={theme} onToggleTheme={toggleTheme} />

      <main className="flex-grow max-w-6xl mx-auto w-full px-4 py-8 md:py-16">
        {status === 'idle' && (
          <div className="max-w-4xl mx-auto animate-in fade-in slide-in-from-bottom-6 duration-700">
            <div className="mb-12">
              <h1 className={`text-6xl md:text-8xl font-black mb-8 tracking-tighter leading-[0.85] ${isDarkMode ? 'text-white' : 'text-slate-900'}`}>
                Gaze<span className="text-emerald-600">.</span>
              </h1>
              <p className={`text-xl ${isDarkMode ? 'text-slate-400' : 'text-slate-500'} mb-12 max-w-2xl leading-relaxed`}>
                High-precision interpupillary distance measurement using Gemini 3 Pro spatial reasoning. No credit card or reference object required.
              </p>

              <div className="flex flex-col sm:flex-row gap-4">
                <button onClick={startCamera} className="px-10 py-5 bg-emerald-600 text-white font-black text-lg rounded-2xl shadow-xl shadow-emerald-200 hover:bg-emerald-700 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3">
                  <Target size={24} /> Start Live Scan
                </button>
                <button 
                  onClick={() => fileInputRef.current?.click()} 
                  className={`px-10 py-5 ${isDarkMode ? 'bg-slate-900 border-slate-700 text-slate-200' : 'bg-white border-slate-200 text-slate-700'} border-2 font-black text-lg rounded-2xl shadow-md hover:bg-slate-50 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3`}
                >
                  <Upload size={24} /> Upload Photo
                </button>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  className="hidden" 
                  accept="image/*" 
                  onChange={handleFileUpload} 
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <FeatureCard 
                icon={<Activity className="text-emerald-600" size={28} />} 
                title="Spatial Mapping" 
                desc="Uses neural depth estimation to calculate dimensions without physical markers." 
                isDark={isDarkMode} 
              />
              <FeatureCard 
                icon={<Target className="text-indigo-600" size={28} />} 
                title="8K Reasoning" 
                desc="Gemini 3 Pro analyzes facial geometry with an optimized 8,192 token thinking budget." 
                isDark={isDarkMode} 
              />
              <FeatureCard 
                icon={<ShieldCheck className="text-emerald-600" size={28} />} 
                title="Secure & Private" 
                desc="Images are processed for analysis and never stored. Results are sub-millimeter accurate." 
                isDark={isDarkMode} 
              />
            </div>
          </div>
        )}

        {status === 'capturing' && (
          <div className="max-w-4xl mx-auto animate-in zoom-in-95 duration-500 flex flex-col gap-8">
            <div className={`relative aspect-[3/4] sm:aspect-video bg-black rounded-[3rem] overflow-hidden border-8 ${isDarkMode ? 'border-slate-800' : 'border-white'} shadow-2xl transition-all`}>
              <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover scale-x-[-1] opacity-90" />
              <IRDotProjector active={true} color="rgba(34, 197, 94" />

              <div className="absolute inset-0 pointer-events-none">
                <div className="absolute inset-0 bg-gradient-to-b from-black/20 via-transparent to-black/20" />
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-80 h-80 border-2 border-dashed border-white/20 rounded-full animate-pulse" />
                <FixationTarget />
              </div>

              <div className="absolute top-6 left-6 right-6 flex justify-between items-start pointer-events-none">
                <div className="px-5 py-2.5 rounded-xl backdrop-blur-xl border border-white/20 bg-black/60 text-white flex items-center gap-3">
                  {isCalibrating ? <Loader2 className="animate-spin text-emerald-400" size={16} /> : <div className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse" />}
                  <span className="text-[10px] font-black uppercase tracking-[0.2em]">
                    {isCalibrating ? 'Calibrating...' : 'Spatial Locked'}
                  </span>
                </div>

                {calibratedIPD && (
                  <div className="px-5 py-3 rounded-xl bg-black/60 backdrop-blur-xl border border-white/10 text-right animate-in fade-in slide-in-from-right-4">
                    <span className="text-[9px] font-black text-emerald-400 uppercase tracking-widest block mb-0.5">Pre-Scan</span>
                    <div className="text-2xl font-black text-white">
                      {calibratedIPD.toFixed(1)}<span className="text-sm opacity-40 ml-0.5">mm</span>
                    </div>
                  </div>
                )}
              </div>
            </div>

            <div className="flex justify-center gap-4">
              <button 
                onClick={() => runIPDAnalysis()} 
                className="px-12 py-5 text-white font-black text-xl rounded-2xl shadow-xl transition-all flex items-center gap-3 hover:scale-[1.02] active:scale-95 bg-emerald-600 shadow-emerald-200"
              >
                <Scan size={24} /> Capture PD
              </button>
              <button onClick={reset} className={`px-10 py-5 ${isDarkMode ? 'bg-slate-900 text-slate-300 border-slate-700' : 'bg-white text-slate-700 border-slate-200'} font-bold text-lg rounded-2xl border-2 shadow-sm hover:opacity-80 transition-all`}>Cancel</button>
            </div>
          </div>
        )}

        {status === 'analyzing' && (
          <div className="max-w-md mx-auto text-center py-32 flex flex-col items-center">
            <div className="w-24 h-24 relative mb-10">
              <div className={`absolute inset-0 border-[4px] ${isDarkMode ? 'border-slate-800' : 'border-emerald-100'} rounded-full`} />
              <div className="absolute inset-0 border-[4px] border-emerald-600 rounded-full border-t-transparent animate-spin" />
              <div className="absolute inset-0 flex items-center justify-center">
                <ImageIcon size={32} className="text-emerald-600 animate-pulse" />
              </div>
            </div>
            <h2 className={`text-3xl font-black ${isDarkMode ? 'text-white' : 'text-slate-900'} tracking-tighter mb-3`}>AI Analyzing</h2>
            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.2em] animate-pulse">Computing Sub-Millimeter Vectors</p>
          </div>
        )}

        {status === 'completed' && result && (
          <div className="max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-12 duration-700">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-20">
              <div className="lg:col-span-5 flex items-center">
                <div className={`relative aspect-square w-full bg-slate-950 rounded-[3rem] overflow-hidden shadow-2xl border-[8px] ${isDarkMode ? 'border-slate-900' : 'border-white'} transition-all`}>
                  <img src={capturedImage} alt="Scan" className="w-full h-full object-cover opacity-80" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent" />

                  <svg className="absolute inset-0 w-full h-full pointer-events-none z-20">
                    <line 
                      x1={`${result.rightPupilCenter[0]/10}%`} y1={`${result.rightPupilCenter[1]/10}%`} 
                      x2={`${result.leftPupilCenter[0]/10}%`} y2={`${result.leftPupilCenter[1]/10}%`} 
                      stroke="#10b981" strokeWidth="3" strokeDasharray="10,5" 
                    />
                    <circle cx={`${result.rightPupilCenter[0]/10}%`} cy={`${result.rightPupilCenter[1]/10}%`} r="10" fill="white" fillOpacity="0.2" stroke="#10b981" strokeWidth="2" />
                    <circle cx={`${result.leftPupilCenter[0]/10}%`} cy={`${result.leftPupilCenter[1]/10}%`} r="10" fill="white" fillOpacity="0.2" stroke="#10b981" strokeWidth="2" />
                  </svg>

                  <div className="absolute bottom-6 left-6 right-6 p-4 bg-black/40 backdrop-blur-2xl rounded-2xl border border-white/10 flex justify-between items-center">
                    <div>
                      <div className="text-[9px] font-black text-emerald-400 uppercase tracking-widest mb-0.5">Precision Density</div>
                      <div className="text-base font-black text-white">{(result.scalingFactor * 100).toFixed(1)} px/mm</div>
                    </div>
                    <CheckCircle className="text-emerald-500" size={24} />
                  </div>
                </div>
              </div>

              <div className="lg:col-span-7 flex flex-col justify-center space-y-10">
                <div>
                  <span className="text-[10px] font-black text-emerald-600 uppercase tracking-[0.4em] mb-4 block">Result Generated</span>
                  <div className="flex items-baseline gap-4 mb-4">
                    <h2 className={`text-[8rem] md:text-[10rem] font-black ${isDarkMode ? 'text-white' : 'text-slate-900'} tracking-tighter leading-none`}>
                      {result.ipdMm.toFixed(1)}
                    </h2>
                    <span className={`text-4xl md:text-5xl font-black ${isDarkMode ? 'text-slate-700' : 'text-slate-200'} italic uppercase`}>mm</span>
                  </div>
                  <p className={`${isDarkMode ? 'text-slate-400' : 'text-slate-500'} text-lg font-medium max-w-lg`}>
                    Measured via {result.calibrationUsed} methodology. {result.explanation}
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <ResultStat label="Confidence" value={`${(result.confidence * 100).toFixed(1)}%`} isDark={isDarkMode} />
                  <ResultStat label="HVID Scaling" value={result.confidenceInterval} isDark={isDarkMode} />
                </div>

                <div className="flex gap-4">
                  <button onClick={reset} className="flex-grow py-6 bg-emerald-600 text-white font-black text-xl rounded-2xl shadow-xl shadow-emerald-200 hover:bg-emerald-700 transition-all flex items-center justify-center gap-3 group">
                    <RefreshCw className="group-hover:rotate-180 transition-transform duration-700" size={24} />
                    New Analysis
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {status === 'error' && (
          <div className={`max-w-xl mx-auto ${isDarkMode ? 'bg-slate-900 border-red-900/30' : 'bg-white border-red-50'} p-12 rounded-[3rem] border shadow-2xl text-center transition-all`}>
            <div className={`w-20 h-20 ${isDarkMode ? 'bg-red-900/20' : 'bg-red-50'} text-red-500 rounded-2xl flex items-center justify-center mx-auto mb-8`}>
              <ShieldAlert size={40} />
            </div>
            <h2 className={`text-3xl font-black ${isDarkMode ? 'text-white' : 'text-slate-900'} mb-4 tracking-tight`}>Analysis Error</h2>
            <p className={`${isDarkMode ? 'text-slate-400' : 'text-slate-500'} mb-10 text-lg leading-relaxed`}>{error}</p>
            <button onClick={reset} className={`w-full py-5 ${isDarkMode ? 'bg-slate-100 text-slate-900 hover:bg-white' : 'bg-slate-900 text-white hover:bg-black'} font-black text-lg rounded-2xl transition-all`}>Return to Dashboard</button>
          </div>
        )}
      </main>

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
}

